		}

		// apply templates to windows desktop labels
		inLabels = r.GetWindowsDesktopLabels(condition)
		if inLabels != nil {
			r.SetWindowsDesktopLabels(condition, applyLabelsTraits(inLabels, traits))
		}

		r.SetHostGroups(condition,
