}

func buildVarExprFromProperty(mapValue, keyValue interface{}) (interface{}, error) {
	namespace, ok := mapValue.(namespaceRef)
	if !ok {
		return nil, trace.BadParameter("invalid variable selector: expected namespace[\"name\"] with exactly two components")
	}
	name, ok := keyValue.(string)
	if !ok {
		return nil, trace.BadParameter("invalid variable selector: expected namespace[\"name\"] with a string name")
	}
	return VarExpr{Namespace: namespace.namespace, Name: name}, nil
}

func validateNamespace(namespace string) error {
	switch namespace {
	case "internal", "external", LiteralNamespace:
		return nil
	default:
		return trace.BadParameter("unsupported variable namespace %q; supported namespaces are internal, external, and literal", namespace)
	}
}

func validateExpr(expr Expr) error {
	return validateExprDepth(expr, 0)
}

func validateExprDepth(expr Expr, depth int) error {
	if expr == nil {
		return trace.BadParameter("expression contains an empty node")
	}
	if depth > maxExpressionDepth {
		return trace.BadParameter("expression exceeds the maximum allowed depth")
	}
	switch node := expr.(type) {
	case StringLitExpr, RegexpMatchExpr:
		return nil
	case *RegexpMatchExpr:
		return nil
	case VarExpr:
		if node.Name == "" {
			return trace.BadParameter("incomplete variable %q: expected namespace.name", node.Namespace)
		}
		return validateNamespace(node.Namespace)
	case EmailLocalExpr:
		if node.Input == nil || node.Input.Kind() != reflect.String {
			return trace.BadParameter("email.local requires a string expression")
		}
		return validateExprDepth(node.Input, depth+1)
	case RegexpReplaceExpr:
		if node.Input == nil || node.Input.Kind() != reflect.String {
			return trace.BadParameter("regexp.replace source must be a string expression")
		}
		if _, err := compileRegexp(node.Pattern); err != nil {
			return err
		}
		return validateExprDepth(node.Input, depth+1)
	case RegexpNotMatchExpr:
		if node.Expr == nil || node.Expr.Kind() != reflect.Bool {
			return trace.BadParameter("regexp.not_match requires a boolean expression")
		}
		return validateExprDepth(node.Expr, depth+1)
	case *RegexpNotMatchExpr:
		if node.Expr == nil || node.Expr.Kind() != reflect.Bool {
			return trace.BadParameter("regexp.not_match requires a boolean expression")
		}
		return validateExprDepth(node.Expr, depth+1)
	case logicalExpr:
		if node.left == nil || node.right == nil || node.left.Kind() != reflect.Bool || node.right.Kind() != reflect.Bool {
			return trace.BadParameter("boolean operator %s requires boolean expressions", node.op)
		}
		if err := validateExprDepth(node.left, depth+1); err != nil {
			return err
		}
		return validateExprDepth(node.right, depth+1)
	default:
		return trace.BadParameter("unsupported expression node %T", expr)
	}
}

func parseEmailLocal(args ...interface{}) (Expr, error) {
	if len(args) != 1 {
		return nil, trace.BadParameter("email.local expects exactly 1 argument, got %d", len(args))
	}
	input, err := stringExpression(args[0], "email.local")
	if err != nil {
		return nil, err
	}
	return EmailLocalExpr{Input: input}, nil
}

func parseRegexpReplace(args ...interface{}) (Expr, error) {
	if len(args) != 3 {
		return nil, trace.BadParameter("regexp.replace expects exactly 3 arguments, got %d", len(args))
	}
	input, err := stringExpression(args[0], "first argument to regexp.replace")
	if err != nil {
		return nil, err
	}
	pattern, ok := args[1].(string)
	if !ok {
		return nil, trace.BadParameter("second argument to regexp.replace must be a constant string pattern, got %T", args[1])
	}
	replacement, ok := args[2].(string)
	if !ok {
		return nil, trace.BadParameter("third argument to regexp.replace must be a constant string replacement, got %T", args[2])
	}
	re, err := compileRegexp(pattern)
	if err != nil {
		return nil, err
	}
	return RegexpReplaceExpr{Input: input, Pattern: pattern, Replacement: replacement, re: re}, nil
}

func parseRegexpMatch(args ...interface{}) (Expr, error) {
	if len(args) != 1 {
		return nil, trace.BadParameter("regexp.match expects exactly 1 argument, got %d", len(args))
	}
	pattern, ok := args[0].(string)
	if !ok {
		return nil, trace.BadParameter("argument to regexp.match must be a constant string pattern, got %T", args[0])
	}
	re, err := compileRegexp(pattern)
	if err != nil {
		return nil, err
	}
	return &RegexpMatchExpr{re: re}, nil
}

func parseRegexpNotMatch(args ...interface{}) (Expr, error) {
	if len(args) != 1 {
		return nil, trace.BadParameter("regexp.not_match expects exactly 1 argument, got %d", len(args))
	}
	matcher, err := parseRegexpMatch(args...)
	if err != nil {
		return nil, err
	}
	return RegexpNotMatchExpr{Expr: matcher}, nil
}

func stringExpression(value interface{}, name string) (Expr, error) {
	switch value := value.(type) {
	case string:
		return StringLitExpr{Value: value}, nil
	case Expr:
		if value.Kind() != reflect.String {
			return nil, trace.BadParameter("%s must be a string expression, got %s", name, value.Kind())
		}
		return value, nil
	default:
		return nil, trace.BadParameter("%s must be a string expression, got %T", name, value)
	}
}

func parseAnd(left, right interface{}) (Expr, error) { return parseBooleanOperator("&&", left, right) }
func parseOr(left, right interface{}) (Expr, error)  { return parseBooleanOperator("||", left, right) }

func parseBooleanOperator(operator string, left, right interface{}) (Expr, error) {
	leftExpr, leftOK := left.(Expr)
	rightExpr, rightOK := right.(Expr)
	if !leftOK || !rightOK || leftExpr.Kind() != reflect.Bool || rightExpr.Kind() != reflect.Bool {
		return nil, trace.BadParameter("operator %s requires boolean expressions", operator)
	}
	return logicalExpr{op: operator, left: leftExpr, right: rightExpr}, nil
}

func parseNot(value interface{}) (Expr, error) {
	expr, ok := value.(Expr)
	if !ok || expr.Kind() != reflect.Bool {
		return nil, trace.BadParameter("operator ! requires a boolean expression")
	}
	return RegexpNotMatchExpr{Expr: expr}, nil
}

func compileRegexp(pattern string) (*regexp.Regexp, error) {
	re, err := regexp.Compile(pattern)
	if err != nil {
		return nil, trace.BadParameter("invalid regexp pattern %q: %v", pattern, err)
	}
	return re, nil
}

// Matcher matches strings against criteria such as a regexp or glob.
type Matcher interface{ Match(in string) bool }

// MatcherFn adapts a function to Matcher.
type MatcherFn func(in string) bool

func (fn MatcherFn) Match(in string) bool { return fn(in) }

// NewAnyMatcher matches when any of the supplied expressions match.
func NewAnyMatcher(in []string) (Matcher, error) {
	matchers := make([]Matcher, len(in))
	for i, value := range in {
		matcher, err := NewMatcher(value)
		if err != nil {
			return nil, trace.Wrap(err)
		}
		matchers[i] = matcher
	}
	return MatcherFn(func(value string) bool {
		for _, matcher := range matchers {
			if matcher.Match(value) {
				return true
			}
		}
		return false
	}), nil
}

// MatchExpression combines static text with a boolean matcher expression.
type MatchExpression struct {
	prefix, suffix string
	m              Expr
}

func (m MatchExpression) Match(in string) bool {
	if !strings.HasPrefix(in, m.prefix) || !strings.HasSuffix(in, m.suffix) || len(in) < len(m.prefix)+len(m.suffix) {
		return false
	}
	middle := strings.TrimPrefix(in, m.prefix)
	if m.suffix != "" {
		middle = strings.TrimSuffix(middle, m.suffix)
	}
	result, err := m.m.Evaluate(EvaluateContext{MatcherInput: middle})
	if err != nil {
		return false
	}
	matched, ok := result.(bool)
	return ok && matched
}

// prefixSuffixMatcher and regexpMatcher keep the historical internal names
// used by package tests and callers.
type prefixSuffixMatcher = MatchExpression
type regexpMatcher = RegexpMatchExpr
type notMatcher = RegexpNotMatchExpr

func newPrefixSuffixMatcher(prefix, suffix string, inner Expr) MatchExpression {
	return MatchExpression{prefix: prefix, suffix: suffix, m: inner}
}

// NewMatcher parses literal, glob, raw regexp, and boolean regexp matcher
// expressions, optionally surrounded by static prefix and suffix text.
func NewMatcher(value string) (Matcher, error) {
	trimmed := strings.TrimSpace(value)
	if !strings.Contains(trimmed, "{{") && !strings.Contains(trimmed, "}}") {
		if strings.ContainsAny(trimmed, "{}") {
			return nil, malformedTemplate(value)
		}
		return newRegexpMatcher(trimmed, true)
	}

	prefix, suffix, body, err := extractTemplate(value)
	if err != nil {
		return nil, err
	}
	expr, err := parse(body)
	if err != nil {
		return nil, trace.BadParameter("invalid matcher expression in %q: %v", value, err)
	}
	if expr.Kind() != reflect.Bool {
		return nil, trace.BadParameter("matcher expression %q must evaluate to a boolean, got %s", value, expr.Kind())
	}
	if err := validateMatcherExpr(expr, 0); err != nil {
		return nil, trace.BadParameter("invalid matcher expression in %q: %v", value, err)
	}
	return newPrefixSuffixMatcher(prefix, suffix, expr), nil
}

func extractTemplate(input string) (prefix, suffix, body string, err error) {
	trimmed := strings.TrimSpace(input)
	open := strings.Index(trimmed, "{{")
	close := strings.Index(trimmed, "}}")
	if open < 0 || close < open+2 || strings.Count(trimmed, "{{") != 1 || strings.Count(trimmed, "}}") != 1 {
		return "", "", "", malformedTemplate(input)
	}
	prefix, suffix = trimmed[:open], trimmed[close+2:]
	if strings.ContainsAny(prefix+suffix, "{}") {
		return "", "", "", malformedTemplate(input)
	}
	body = strings.TrimSpace(trimmed[open+2 : close])
	if body == "" {
		return "", "", "", malformedTemplate(input)
	}
	return prefix, suffix, body, nil
}

func validateMatcherExpr(expr Expr, depth int) error {
	if depth > maxExpressionDepth {
		return trace.BadParameter("matcher expression exceeds the maximum allowed depth")
	}
	switch node := expr.(type) {
	case RegexpMatchExpr, *RegexpMatchExpr:
		return nil
	case RegexpNotMatchExpr:
		return validateMatcherExpr(node.Expr, depth+1)
	case *RegexpNotMatchExpr:
		return validateMatcherExpr(node.Expr, depth+1)
	case logicalExpr:
		if err := validateMatcherExpr(node.left, depth+1); err != nil {
			return err
		}
		return validateMatcherExpr(node.right, depth+1)
	default:
		return trace.BadParameter("matcher expressions cannot contain variables or string expressions")
	}
}

func newRegexpMatcher(raw string, escape bool) (*regexpMatcher, error) {
	pattern := raw
	if escape && !strings.HasPrefix(raw, "^") && !strings.HasSuffix(raw, "$") {
		pattern = "^" + utils.GlobToRegexp(raw) + "$"
	}
	re, err := compileRegexp(pattern)
	if err != nil {
		return nil, err
	}
	return &RegexpMatchExpr{re: re}, nil
}

// transformer is retained for compatibility with expressions constructed by
// older package clients.
type transformer interface {
	transform(in string) (string, error)
}

type emailLocalTransformer struct{}

func (emailLocalTransformer) transform(in string) (string, error) {
	result, err := (EmailLocalExpr{Input: StringLitExpr{Value: in}}).Evaluate(EvaluateContext{})
	if err != nil {
		return "", err
	}
	return result.([]string)[0], nil
}

type regexpReplaceTransformer struct {
	re          *regexp.Regexp
	replacement string
}

func newRegexpReplaceTransformer(pattern, replacement string) (*regexpReplaceTransformer, error) {
	re, err := compileRegexp(pattern)
	if err != nil {
		return nil, err
	}
	return &regexpReplaceTransformer{re: re, replacement: replacement}, nil
}

func (r regexpReplaceTransformer) transform(in string) (string, error) {
	if !r.re.MatchString(in) {
		return "", nil
	}
	return r.re.ReplaceAllString(in, r.replacement), nil
}

func (r regexpReplaceTransformer) String() string {
	return fmt.Sprintf("regexp.replace(%q, %q)", r.re.String(), r.replacement)
}

